   758      AllDirections       = 0x20000000,   /* If set, this subtable will be applied to
   759                                           * both horizontal and vertical text (i.e.
   760                                           * the state of bit 0x80000000 is ignored). */
   761      Logical             = 0x10000000,   /* If set, this subtable will process glyphs
   762                                           * in logical order (or reverse logical order,
   763                                           * depending on the value of bit 0x80000000). */
   764      Reserved            = 0x0FFFFF00,   /* Reserved, set to zero. */
   765      SubtableType        = 0x000000FF,   /* Subtable type; see following table. */
