   784      case Ligature:              return_trace (c->dispatch (u.ligature));
   785      case Noncontextual:         return_trace (c->dispatch (u.noncontextual));
   786      case Insertion:             return_trace (c->dispatch (u.insertion));
   787      default:                    return_trace (c->default_return_value ());
   788      }
   789    }
